"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/trust-security/variants/01-enterprise-readiness";
import View1 from "./components/trust-security/variants/02-compliance-marks";
import View2 from "./components/trust-security/variants/03-security-safeguards";
import View3 from "./components/trust-security/variants/04-reliability-summary";
const variants = {"enterprise-readiness":View0,"compliance-marks":View1,"security-safeguards":View2,"reliability-summary":View3};
export interface ArtemisTrustSecurityProps { className?: string; variant?: "enterprise-readiness" | "compliance-marks" | "security-safeguards" | "reliability-summary"; }
export function ArtemisTrustSecurity({ className, variant = "enterprise-readiness" }: ArtemisTrustSecurityProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}
